/**
 * Форматирование даты
 * Вход: "02.02.2026 16:23:53"
 * Выход: "02.02.26" или "02.02.26 16:23"
 */
function formatDate(dateStr) {
  if (!dateStr) return "-";
  try {
    // Пример входного формата: "02.02.2026 16:23:53"
    // Приводим к единому виду
    const normalized = String(dateStr).trim().replace(/-/g, ".").replace("T", " ");
    const parts = normalized.split(" ");
    if (parts.length >= 1) {
      const dateParts = parts[0].split(".");
      if (dateParts.length === 3) {
        // Формат: DD.MM.YY
        let dd, mm, yy;
        if (dateParts[0].length === 4) {
          // 2026.02.02
          [yy, mm, dd] = dateParts;
        } else {
          // 02.02.2026
          [dd, mm, yy] = dateParts;
        }
        let formatted = `${dd}.${mm}.${yy.substring(2)}`;
        if (parts.length >= 2 && parts[1]) {
          const timeParts = parts[1].split(":");
          if (timeParts.length >= 2) {
            formatted += ` ${timeParts[0]}:${timeParts[1]}`;
          }
        }
        return formattedDate;
      }
    }
    return dateStr;
  } catch (e) {
    console.error("Error formatting date:", e);
    return dateStr;
  }
}

// URL дефолтной иконки отчета
const DEFAULT_REPORT_ICON = "https://bitrix24public.com/b24-9j211s.bitrix24.ru/docs/pub/7119208d5b6ceb0f1e06b77d4e2fd655/showFile/?&token=7qh3p4zbj0qb";

//Определение текста кнопки на основе статуса отчета

function getButtonLabel(report) {
  const editableStatuses = ["in_work_ou", "never_login", "returned_for_revision"];
  const statusSystemName = report.status_system_name || "";
  return editableStatuses.includes(statusSystemName) ? "Заполнить" : "Просмотреть";
}

// Шаблон отдельной карточки отчета

function cardTemplate(report) {
  // Определяем цвет статуса (берем из данных или дефолтный серый)
  const statusColor = report.status_color && report.status_color !== "null" ? report.status_color : "#999999";

  // Форматируем дату
  const formattedDate = formatDate(report.status_date);
  const dateHtml = formattedDate && formattedDate !== "-" ? `<div class="date-separator">|</div>
     <div class="date-text">${formattedDate}</div>` : "";

  // Определяем текст кнопки
  const buttonLabel = getButtonLabel(report);

  // Определяем URL или SVG иконки (если есть в данных, используем её, иначе дефолтную)
  const iconValue = report["Иконка"] || DEFAULT_REPORT_ICON;
  let iconHtml = '';

  // Проверяем, пришел ли SVG-код напрямую
  if (false && typeof iconValue === 'string' && iconValue.trim().toLowerCase().startsWith('<svg')) {
    let cleanSvg = iconValue;

    // Ищем открывающий тег <svg ...> чтобы переопределить его размеры
    const svgTagMatch = cleanSvg.match(/<svg[^>]*>/i);
    if (svgTagMatch) {
      let svgTag = svgTagMatch[0];
      // Удаляем жестко заданные width="800px" и height="800px"
      svgTag = svgTag.replace(/\s(width|height)=(['"])[^'"]*\2/gi, '');
      // Добавляем width="100%" и height="100%", чтобы SVG четко встал в наши 40x40
      svgTag = svgTag.replace(/<svg/i, '<svg width="100%" height="100%" style="display: block;"');
      // Заменяем оригинальный тег на очищенный
      cleanSvg = cleanSvg.replace(svgTagMatch[0], svgTag);
    }

    // Оборачиваем в div фиксированного размера 40x40
    iconHtml = `
      <div class="report-icon-svg" style="width: 40px; height: 40px; flex-shrink: 0; display: flex; align-items: center; justify-content: center;">
        ${cleanSvg}
      </div>`;
  } else {
    if (false) {
      // Если это обычная ссылка, выводим как картинку
      iconHtml = `
      <img src="${iconValue}" 
           alt="${report["Наименование отчета"] || "Иконка"}" 
           class="report-icon-image" 
           style="width: 40px; height: 40px; object-fit: contain; flex-shrink: 0;" />`;
    }
  }
  return `
  <div class="report-card" 
       data-id="${report.report_pk_id}" 
       data-system-name="${report.report_system_name || ""}"
       data-status="${report.status_name || ""}"
       data-status-system-name="${report.status_system_name || ""}">
    <div class="card-header">
      <h3 class="report-title" title="${report.report_name || ""}">
          ${report.report_name || "Без названия"}
        </h3>
      ${iconHtml}
    </div>
    <div class="card-footer">
      <div class="status-indicator">
        <span class="status-dot" style="background-color: ${statusColor};"></span>
          <span class="status-text">${report.status_name || "-"}</span>
      </div>
            ${dateHtml}
    </div>
    <div class="card-action">
      <button class="report-action-btn" data-report-id="${report.report_pk_id}">
        ${buttonLabel}
      </button>
    </div>
  </div>
`;
}

// Кэш последнего выбранного отчета для прямого доступа
let lastSelectedReport = null;
let parsedReportsCache = [];
let lastReportsData = [];

/**
 * Обновление primary цвета для кнопок
 * Читает значение из модели и устанавливает CSS переменную
 */
function updatePrimaryColor() {
  const primaryColor = appsmith.model.primary_color || "#553DE9";
  document.documentElement.style.setProperty("--widget-primary-color", primaryColor);
}

/**
 * Обработка клика по кнопке действия
 */
function handleActionButtonClick(e) {
  const button = e.currentTarget;
  const reportId = button.dataset.reportId;

  // Ищем отчет в кэше распарсенных данных
  let selectedReport = null;
  if (parsedReportsCache && parsedReportsCache.length > 0) {
    selectedReport = parsedReportsCache.find(r => r.report_pk_id == reportId);
  }
  console.log("Нажата кнопка для отчета:", selectedReport);
  if (!selectedReport) {
    console.error("Отчет не найден для ID:", reportId);
    return;
  }

  // Сохраняем последний выбранный отчет для прямого доступа
  lastSelectedReport = selectedReport;

  // Обновляем модель с выбранным отчетом
  appsmith.updateModel({
    selectedReport: selectedReport,
    selectedReportId: reportId,
    selectedReportSystemName: selectedReport.report_system_name || "",
    selectedReportStatus: selectedReport.status_name || "",
    _triggeredReport: selectedReport
  });
  console.log("Модель виджета обновлена. Доступ к данным через:");
  console.log("- CustomWidget.selectedReport");
  console.log("- CustomWidget.selectedReportId");
  console.log("- CustomWidget._triggeredReport");
  try {
    appsmith.triggerEvent("onActionButtonClick", selectedReport);
  } catch (err) {
    console.error("Ошибка при вызове события:", err);
  }
}

/**
 * Рендеринг всех карточек
 */
function renderCards(reports) {
  const gridContainer = document.querySelector(".reports-grid");
  if (!gridContainer) {
    console.error("Grid container не найден");
    return;
  }
  if (!reports || reports.length === 0) {
    gridContainer.innerHTML = '<div class="no-data">Нет данных для отображения</div>';
    return;
  }

  // Рендерим карточки
  gridContainer.innerHTML = reports.map(cardTemplate).join("");

  // Добавляем обработчики событий для кнопок
  document.querySelectorAll(".report-action-btn").forEach(button => {
    button.addEventListener("click", handleActionButtonClick);
  });
}

// сравнение двух массивов отчетов 
function areReportsEqual(oldReports, newReports) {
  if (!oldReports && !newReports) return true;
  if (!oldReports || !newReports) return false;
  if (oldReports.length !== newReports.length) return false;
  for (let i = 0; i < oldReports.length; i++) {
    const a = oldReports[i];
    const b = newReports[i];
    if (a.report_id !== b.report_id) return false;
    const keyFields = ["report_name", "status_name", "status_system_name", "status_color", "report_system_name"];
    for (const f of keyFields) {
      if (a[f] !== b[f]) return false;
    }
  }
  return true;
}

// Парсинг данных из JSON-строки или объекта

function parseReportsData(reportsData) {
  if (!reportsData) {
    parsedReportsCache = [];
    return [];
  }

  // Если это строка, парсим её
  if (typeof reportsData === "string") {
    try {
      const parsed = JSON.parse(reportsData);
      parsedReportsCache = Array.isArray(parsed) ? parsed : [];
      return parsedReportsCache;
    } catch (e) {
      console.error("Error parsing reports data:", e);
      parsedReportsCache = [];
      return [];
    }
  }

  // Если это массив, возвращаем как есть
  if (Array.isArray(reportsData)) {
    parsedReportsCache = reportsData;
    return parsedReportsCache;
  }

  // Если это объект с массивом внутри
  if (typeof reportsData === "object" && reportsData !== null) {
    parsedReportsCache = Array.isArray(reportsData) ? reportsData : [];
    return parsedReportsCache;
  }
  parsedReportsCache = [];
  return [];
}

/**
 * Инициализация виджета
 */
appsmith.onReady(() => {
  const gridContainer = document.querySelector(".reports-grid");
  if (!gridContainer) {
    console.error("Grid container не найден в DOM");
    return;
  }

  // Обновляем primary цвет из модели
  updatePrimaryColor();

  // Первичный рендеринг
  if (appsmith.model && appsmith.model.reports) {
    const parsedReports = parseReportsData(appsmith.model.reports);
    lastReportsData = parsedReports; // Сохраняем начальное состояние
    renderCards(parsedReports);
  } else {
    // Если данных нет, показываем сообщение
    gridContainer.innerHTML = '<div class="no-data">Нет данных для отображения</div>';
  }

  // Слушатель изменений модели
  // Перерисовка происходит только если массив reports действительно изменился
  if (typeof appsmith.onModelChange === "function") {
    appsmith.onModelChange(newModel => {
      // Обновляем primary цвет при изменении модели
      updatePrimaryColor();
      if (newModel.reports) {
        const parsedReports = parseReportsData(newModel.reports);

        // Сравниваем с предыдущим состоянием
        // Ререндеринг только если массив отчетов изменился
        if (!areReportsEqual(lastReportsData, parsedReports)) {
          lastReportsData = parsedReports;
          renderCards(parsedReports);
        }
      }
    });
  }
});

// Функция для принудительного обновления (может быть вызвана извне)

function refreshCards() {
  if (appsmith.model && appsmith.model.reports) {
    const parsedReports = parseReportsData(appsmith.model.reports);
    renderCards(parsedReports);
  }
}

// Экспорт функций для внешнего использования (если нужно)
if (typeof window !== "undefined") {
  window.ReportsWidget = {
    refresh: refreshCards,
    render: renderCards,
    formatDate: formatDate,
    parseReportsData: parseReportsData,
    getLastSelectedReport: () => lastSelectedReport
  };
}

