  padding-top: 12px;
  border-top: 1px solid rgba(0, 0, 0, 0.06);
  flex-shrink: 0;
}

/* Индикатор статуса */
.status-indicator {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
  max-width: calc(100% - 80px);
  overflow: hidden;
}

/* Точка статуса */
.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
