  font-size: 10px;
  color: #888;
  flex-shrink: 0;
  white-space: nowrap;
  font-weight: 400;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

/* Панель действий карточки */
.card-action {
  margin-top: 8px;
  display: flex;
  justify-content: center;
  flex-shrink: 0;
}

/* Кнопка действия */
.report-action-btn {
  width: 100%;
  padding: 8px 12px;
  background-color: var(--widget-primary-color, #553de9);
  color: white;
  border: none;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 2px 4px rgba(85, 61, 233, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

.report-action-btn:hover {
  background-color: var(--widget-primary-color, #553de9);
  filter: brightness(0.9);
  box-shadow: 0 4px 8px rgba(85, 61, 233, 0.3);
  transform: translateY(-1px);
}

.report-action-btn:active {
  transform: translateY(0);
  box-shadow: 0 1px 2px rgba(85, 61, 233, 0.2);
}

.report-action-btn:focus {
  outline: 2px solid var(--widget-primary-color, #553de9);
  outline-offset: 2px;
}

.report-action-btn:focus:not(:focus-visible) {
